impl Config {
    fn read() -> Result<Self> {
        let path = std::env::var_os("ZARK_REAL_FLOW_CONFIG")
            .context("set ZARK_REAL_FLOW_CONFIG to an authenticated tool/manifest pin config")?;
        let result: Self = serde_json::from_slice(&fs::read(path)?)?;
        ensure!(
            hash(&[&fs::read(&result.manifest)?]) == hex32(&result.manifest_sha256)?,
            "integration manifest pin mismatch"
        );
        for pin in [
            &result.nargo,
            &result.bb,
            &result.bitcoind,
            &result.bitcoin_cli,
        ] {
            ensure!(
                pin.path.is_absolute() && hash(&[&fs::read(&pin.path)?]) == hex32(&pin.sha256)?,
                "integration executable pin mismatch"
            );
        }
        ensure!(
            result.run_parent.is_absolute(),
            "integration run parent must be absolute"
        );
        Ok(result)
    }
}

fn private_dir(path: &Path) -> Result<()> {
    fs::DirBuilder::new().mode(0o700).create(path)?;
    fs::File::open(path.parent().context("private directory parent")?)?.sync_all()?;
    Ok(())
}

fn write_private(path: &Path, bytes: &[u8]) -> Result<()> {
    let mut file = fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .mode(0o600)
        .open(path)?;
    file.write_all(bytes)?;
    file.sync_all()?;
    fs::File::open(path.parent().context("private file parent")?)?.sync_all()?;
    Ok(())
}

/// Only a fresh, locally started regtest node is ever used by this test.
fn verifier(
    config: &Config,
    manifest: &Manifest,
    deployment: &Deployment,
) -> Result<PinnedVerifier> {
    deployment.verifier(
        manifest,
        config.manifest.parent().context("manifest directory")?,
        ArtifactPin {
            path: config.bb.path.clone(),
            sha256: hex32(&config.bb.sha256)?,
        },
        &config.crs,
    )
}

